// Uses status codes defined in <stdlib.h>

void terminate_handler(int status) {
    if (status != 0) {
        // Immediate termination signaling error
        exit(EXIT_FAILURE);
    }

    // Program ends successfully
    exit(EXIT_SUCCESS); 
}

// exit() bypasses return path and cleanup.
// Function calls after exit() are unreachable.
